"""mutant_table.py <results-dir> <out.md>: the campaign's table from every stream's results.json and the leg logs,
each named check with the FAIL line the leg printed for it, words as printed."""
import json
import re
import sys
from pathlib import Path

root, out = Path(sys.argv[1]), Path(sys.argv[2])
lines = ['# #806 parent mutant campaign (milan_dp gptp leg)', '',
         'Generated by `scripts/mutant_table.py` from each stream\'s `results.json` and logs.', '',
         '| Stream | Run | Verdict | Leg rc | Named checks failed | Other FAIL lines |', '|---|---|---|---:|---:|---:|']
detail = ['', '## Each named check and the line it printed', '']
for stream in sorted(p for p in root.iterdir() if p.is_dir()):
    for row in json.loads((stream / 'results.json').read_text()):
        tag = row.get('tag', 'C0')
        name = row['mutant']
        failed = row.get('all_failed', [])
        named = row.get('named', [])
        other = [f for f in failed if f not in named]
        lines.append(f"| {stream.name} | {tag} {name} | {row['verdict']} | {row.get('rc', '-')} | "
                     f"{len(named) - len(row.get('not_failed', []))} of {len(named)} | {len(other)} |")
        if tag == 'C0':
            continue
        log = (stream / f'{tag}.log').read_text()
        detail.append(f'### {tag} {name}')
        detail.append('')
        detail.append(f"File `{row['file']}`, planted once (pattern counts {row['pattern_counts']}).")
        detail.append('')
        for check in named:
            hit = [l.strip() for l in log.splitlines() if re.match(r'\s*FAIL\s+' + re.escape(check) + r'\s+got\s', l)]
            detail.append(f'- `{hit[0]}`' if hit else f'- NOT FAILED: {check}')
        tally = [l.strip() for l in log.splitlines() if re.search(r'\d+ checks: \d+ PASS, \d+ FAIL', l)]
        detail.append(f"- tally: `{tally[-1]}`" if tally else '- tally: none printed')
        detail.append('')
out.write_text('\n'.join(lines + detail) + '\n')
print(f'wrote {out}')
